Object.assign(SNIP,{"h3tpl": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Thi offline: đọc ghi file; thi online: tự dùng bàn phím/màn hình\n    if (fopen(\"TENBAI.INP\", \"r\")) {\n        freopen(\"TENBAI.INP\", \"r\", stdin);\n        freopen(\"TENBAI.OUT\", \"w\", stdout);\n    }\n    // ... lời giải ...\n    return 0;\n}"});PRESET_NOTES["l3"]={"Ví dụ: Khung chương trình, bài TONG": "Ô dữ liệu đang là nội dung file TONG.INP. Bấm Chạy: kết quả nằm trong file TONG.OUT, không in ra màn hình. Bỏ chọn ô “Có sẵn file” rồi chạy lại: chương trình đọc bàn phím, in ra màn hình.", "Ví dụ: Sai tên file": "Code mở tong.inp (chữ thường) trong khi file có tên TONG.INP. Mở thất bại nên cin không đọc được gì, a và b giữ giá trị 0, file TONG.OUT ghi 0. Khi chấm, bài này sai mọi test. Ở đây không dùng if (fopen(...)) để thấy rõ hậu quả.", "Ví dụ: Đọc đến hết file": "Không biết trước có bao nhiêu số. Vòng while dừng khi cin >> x không đọc được nữa (hết file). Số nằm trên một dòng hay nhiều dòng đều như nhau.", "Ví dụ: Đọc một dòng có dấu cách": "Họ tên có dấu cách nên phải đọc cả dòng bằng getline. Sau cin >> n, ký tự xuống dòng vẫn còn trong bộ đệm: cin.ignore() bỏ nó đi, nếu không getline đầu tiên sẽ đọc được một dòng rỗng."};EX_HINTS["l3"]=[["Tổng có thể tới 10¹², vượt int: dùng long long.", "In số thực 2 chữ số: cout << fixed << setprecision(2) << ...;", "Chia số thực: (double)s / n, không phải s / n (chia nguyên)."], ["Số chẵn là số chia 2 dư 0. Với số âm lẻ, x % 2 bằng −1 (không phải 1), nên kiểm tra x % 2 == 0 thay vì x % 2 != 1."], ["while (cin >> x) dừng khi hết dữ liệu.", "Tổng có thể vượt int."]];
