const PR3=[{label:"Ví dụ: Khung chương trình, bài TONG",input:"1000000000 2000000000",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"TONG.INP\", \"r\")) {\n        freopen(\"TONG.INP\", \"r\", stdin);\n        freopen(\"TONG.OUT\", \"w\", stdout);\n    }\n    long long a, b;\n    cin >> a >> b;\n    cout << a + b << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Sai tên file",input:"1000000000 2000000000",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    freopen(\"tong.inp\", \"r\", stdin);\n    freopen(\"TONG.OUT\", \"w\", stdout);\n    long long a = 0, b = 0;\n    cin >> a >> b;\n    cout << a + b << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Đọc đến hết file",input:"5 -2 7\n100\n3 3",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"TONGF.INP\", \"r\")) {\n        freopen(\"TONGF.INP\", \"r\", stdin);\n        freopen(\"TONGF.OUT\", \"w\", stdout);\n    }\n    long long x, s = 0;\n    int dem = 0;\n    while (cin >> x) {\n        s += x;\n        dem++;\n    }\n    cout << dem << \" \" << s << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["x","s","dem"]}]},{label:"Ví dụ: Đọc một dòng có dấu cách",input:"2\nNguyen Van An\nTran Thi Binh",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"TEN.INP\", \"r\")) {\n        freopen(\"TEN.INP\", \"r\", stdin);\n        freopen(\"TEN.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    cin.ignore();          // bỏ ký tự xuống dòng còn lại sau số n\n    for (int i = 1; i <= n; i++) {\n        string s;\n        getline(cin, s);\n        cout << i << \". \" << s << \"\\n\";\n    }\n    return 0;\n}"}];
